from fractions import Fraction
import json
from apply_di7_ap_as_01 import G,R,A,info,encoded

def read(p):return json.loads(p.read_bytes())

def allocation(rows,reduction):
    amounts={}
    for kind,amount in rows: amounts[kind]=amounts.get(kind,0)+amount
    total=sum(amounts.values());budget=min(reduction,total)
    shares={k:Fraction(budget*a,total) if total else Fraction(0) for k,a in amounts.items()}
    allocated={k:int(s) for k,s in shares.items()}
    for k in sorted(amounts,key=lambda k:(-(shares[k]-allocated[k]),k))[:budget-sum(allocated.values())]:allocated[k]+=1
    return allocated,{k:amounts[k]-allocated[k] for k in amounts}

